import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import test from "node:test";

import {
  canonicalQuotePdfAttestationBytes,
  signQuotePdfAttestation,
} from "@/server/quote-pdf/attestation";

const payload = {
  tenantId: "00000000-0000-4000-8000-000000000001",
  actorUserId: "00000000-0000-4000-8000-000000000002",
  quoteVersionId: "00000000-0000-4000-8000-000000000003",
  renderFileId: "00000000-0000-4000-8000-000000000004",
  contentFingerprint: "a".repeat(64),
  bucketId: "tenant-files",
  objectPath: "00000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000004/offert-1.pdf",
  checksumSha256: "b".repeat(64),
  sizeBytes: 42,
  mimeType: "application/pdf",
  correlationId: "00000000-0000-4000-8000-000000000005",
  keyId: "test_v1",
  issuedAt: "2026-08-31T12:34:56.789Z",
  expiresAt: "2026-08-31T12:39:56.789Z",
  generationStartedAt: "2026-08-31T12:34:56.789Z",
} as const;

// These exact bytes/HMAC are also reproducible by
// public.quote_pdf_attestation_payload + extensions.hmac in the migration.
test("[10.9][P0] canonical quote-PDF attestation golden vector is stable", () => {
  assert.equal(
    Buffer.from(canonicalQuotePdfAttestationBytes(payload)).toString("hex"),
    "",
  );
  assert.equal(
    signQuotePdfAttestation(payload, "local-test-only-quote-pdf-attestation-secret-v1"),
    "a6114318c48686198dc45f65bdfb5f8803bfd6140204585e6aaa524d36e1bdc0",
  );
});

test("[10.9][P0] attestation stays mechanically Node-only", () => {
  const source = readFileSync(resolve(process.cwd(), "src/server/quote-pdf/attestation.ts"), "utf8");
  assert.match(source, /from "node:crypto"/);
  assert.doesNotMatch(source, /"use client"/);
});
